// 'Optimization': reuse a fixed pool of scratch objects across requests
const POOL = Array.from({ length: 10000 }, () => ({ a: 0, b: 0, c: 0 }));
let idx = 0;
function getScratch() {
  const o = POOL[idx]; idx = (idx + 1) % POOL.length;
  o.a = 0; o.b = 0; o.c = 0; // reset
  return o;
}
// ...used once per request and then discarded conceptually

function promotedObjects(survivalCounts) {
  // survivalCounts: { name: numberOfScavengesSurvived }
  const PROMOTE_AFTER = 2;   // survive this many Scavenges, then tenure
  const promoted = [];
  for (const name in survivalCounts) {
    if (survivalCounts[name] >= PROMOTE_AFTER - 1) {
      promoted.push(name);
    }
  }
  return promoted;
}

