class Arena {
  constructor(size) {
    this.slots = new Array(size).fill(null).map(() => ({ buf: new Uint8Array(256), used: false }));
    this.freeList = this.slots.map((_, i) => i);
  }
  alloc() {
    const i = this.freeList.pop();
    const slot = this.slots[i];
    slot.used = true;
    return slot.buf;          // hand out the backing buffer
  }
  free(buf) {
    for (const slot of this.slots) {
      if (slot.buf === buf) {
        slot.used = false;
        this.freeList.push(this.slots.indexOf(slot));
        return;
      }
    }
  }
}
